CREATE TABLE ETL_PROCESS.T_ETL_WAREHOUSE_CONFIRMED_PROCESSING_L9V (
   WH_SID                              NUMBER          NOT NULL COMMENT 'The unique identifier(surrogate key) of  warehouse',
   TASK_ID                             VARCHAR(20)     NOT NULL COMMENT 'Code of Warehouse Task',
   TASK_POS_NR                         VARCHAR(20)     NOT NULL COMMENT 'Position Number of Warehouse Task',
   WH_CD                               VARCHAR(5)      COMMENT 'Warehouse code',
   WH_PROCESSING_ORDER_NR              VARCHAR(20)     COMMENT 'Warehouse processing order number generated for each warehouse process involving inbound, outbound and all other types of warehouse movements.',
   WH_PROCESS_TYPE_CD                  VARCHAR(5)      COMMENT 'The code for warehouse process type (2010, 2011, etc)',
   ORIGIN_STORAGE_UNIT_NR              VARCHAR(100)    COMMENT 'Origin storage unit number of Warehouse Tasks Confirmed (Package number)',
   WAVE_ID                             VARCHAR(20)     COMMENT 'Number of wave (aggregation of positions which have the same picking process in the warehouse)',
   PACK_SORT_TRACK_NAME                VARCHAR(100)    COMMENT 'Planned bin for the handling unit ("S1-04", "S1-05", "S1-06"',
   ORIGIN_STORAGE_TYPE_CD              VARCHAR(10)     COMMENT 'The type of storage within the warehouse where the processing of the task begins (e.g. Pickbereich, Reservebereich, Eingangsstore, etc.)',
   DEST_STORAGE_TYPE_CD                VARCHAR(10)     COMMENT 'The type of storage within the warehouse where the processing of the task ends (e.g. Pickbereich, Reservebereich, Eingangsstore, etc.)',
   DEST_STORAGE_SUBTYPE_CD             VARCHAR(10)     COMMENT 'The storage section within a certain storage type in the warehouse where the processing of the task ends (e.g. wine storage section)',
   SORT_TRACK_NAME                     VARCHAR(100)    COMMENT 'Sorting track where a sorting trolley is placed on after picking articles ("S1-05-03", "S2-04-02")',
   PROD_QTY                            NUMBER(38, 0)   COMMENT 'The actual quantity of the product in base Unit of Measure',
   TGT_PICK_QTY                        NUMBER(38, 5)   COMMENT 'The quantity that has to be picked when a warehouse order is created',
   PROD_VARIANT_SID                    NUMBER          COMMENT 'The unique identifier (surrogate key) for the product variant',
   PROD_VARIANT_NR                     VARCHAR(20)     COMMENT 'The product variant number',
   WH_STOCK_AVAIL_TYPE_CD              VARCHAR(5)      COMMENT 'The code for the availability type of warehouse stock (e.g. F1 = freely available stock, S1 = blocked stock, F2 = Venlo stock)',
   WH_TASK_PROCESSING_STATUS_CD        VARCHAR(5)      COMMENT 'The Warehouse Task Processing Status Code is representing the specific granualar status of a warehouse task. It can be: NULL/ Empty = Open, A = Canceled, B = Waiting, C = Confirmed',
   WH_TASK_CREATE_TMSP                 TIMESTAMP_TZ(9) COMMENT 'Creation date of a confirmed or open warehouse task',
   WH_PROCESSING_ORDER_CREATED_BY_NAME VARCHAR(20)     COMMENT 'The user who created the warehouse processing order in the EWM system (e.g. number in the format like LUD-LAG-.../ PIL-LAG..  etc --> Spared warehouse device where employee can log into and create a task, 8-digit number --> Personal user account of an employee, number starting with RFC --> User accounts of machines in the warehouse, which automatically create a task) ',
   WH_PROCESSING_ORDER_CONFIRMED_BY_NAME VARCHAR(20)     COMMENT 'The user who confirmed the creation of the warehouse processing order in the EWM system (e.g. number in the format like LUD-LAG-.../ PIL-LAG..  etc --> Spared warehouse device where employee can log into and confirm a task, 8-digit number --> Personal user account of an employee, number starting with RFC --> User accounts of machines in the warehouse, which automatically confirm a task)',
   WH_TASK_CONFIRM_TMSP                TIMESTAMP_TZ(9) COMMENT 'Time of Confirmation of Warehouse Tasks Confirmed',
   DEST_STORAGE_UNIT_NR                VARCHAR(50)     COMMENT 'Destination storage unit number of Warehouse Tasks Confirmed (Package number)',
   STORAGE_QUEUE_NAME                  VARCHAR(20)     COMMENT 'The name of the queue for the articles processed with the particular task. For each storage type, there is a separate queue. (e.g. Internal, P-ALC-WARM, etc,)',
   PROD_CONDITION_CD                   VARCHAR(20)     COMMENT 'The condition code of the product. (01 - can be sold online, 02 - needs to be checked, 03 - for scrapping). Commonly referred to as batch.',
   STORAGE_PROCESS_TYPE_CD             VARCHAR(10)     COMMENT 'This code denotes a type of storage process that summarizes storage process steps in order to define complex processes for putaway, stock removal, and warehouse internal movements (e.g. a goods receipt process may contain the storage process steps for unloading and putaway, whereas a goods issue process may contain the storage process steps for stock removal, packing, staging and loading).',
   STORAGE_PROCESS_STEP_CD             VARCHAR(10)     COMMENT 'This code defines the specific storage process step is part of the storage process (e.g. Unload, Count, Deconsolidate, Put Away, Remove from Stock, Pack, etc.)',
   ORIGIN_RESOURCE_NAME                VARCHAR(20)     COMMENT 'The name of the resource (tool) used for counting the articles processed with the particular task at the source location. Not all processes require counting at the source location, so sometimes this field can be left as null.',
   DEST_RESOURCE_NAME                  VARCHAR(20)     COMMENT 'The name of the resource (tool) used for counting the articles processed with the particular task at the destination location. Not all processes require counting at the destination, so sometimes this field can be left as null.',
   TASK_PROCESSING_START_TMSP          TIMESTAMP_LTZ(9) COMMENT 'The timestamp showing when the processing of the task started',
   ENTIRE_HANDLING_UNIT_FG             BOOLEAN         COMMENT 'This flag denotes if an entire handling unit is used for the processing of the particular task (e.g. when just one article has remained on the handling unit or when all articles on the handling unit are processed by the same task)',
   UOM_SID                             NUMBER          COMMENT 'A surrogate key for the unit of measure of the processed product quantity',
   UOM_CD                              VARCHAR(5)      COMMENT 'A code for the unit of measure of the processed product quantity (e.g. ST = Stück)',
   WH_ORDER_SID                        NUMBER          COMMENT 'The unique identifier (surrogate key) for a warehouse order',
   SRC_WH_ORDER_ID                     VARCHAR(64)     COMMENT 'The unique ID coming from the source for the document generated for the particular warehouse movement. (docid in the source system)',
   WH_ORDER_POS_SID                    NUMBER(38,0)    COMMENT 'The unique surrogate key within the DWH for the position within the document generated to record the warehouse movement. There can be multiple document positions within one document which reference the same product but represent different process steps within the warehouse movement. (generated from itemid + sap_client_id + sap_sys_name from the source)',
   SRC_WH_ORDER_POS_ID                 VARCHAR(64)     COMMENT 'The unique ID coming from the source for the position within the document generated to record the warehouse movement. There can be multiple document positions within one document which reference the same product but represent different process steps within the warehouse movement (itemid in the source system).',
   DIFF_PROCESSED_PROD_QTY             NUMBER(38,14)   COMMENT 'The difference between the product quantity that initially had to be processed with the task and the quantity that was actually processed.',
   STOCK_OWNER_CD                      VARCHAR(10)     COMMENT 'The code of the owner of the articles processed with the particular task. In most cases this code is the same as the warehouse code. Sometimes, the owner can be the stationary business, i.e. the stores. Whenever a stock at the Venlo warehouse arrives for the first time from a supplier, the stock owner is going to be Venlo. Otherwise, the stock owner at the Venlo warehouse is going to be the warehouse that the stock is intended for, i.e. the warehouse where the stock is going to be shipped.',
   CONSOLIDATION_GRP_NAME              VARCHAR(20)     COMMENT 'The name of the consolidation group that the articles processed with the particular task belong to. The consolidation group denotes where the warehouse the articles are going to be sorted.',
   STOCK_AVAIL_TMSP                    TIMESTAMP_LTZ(9) COMMENT 'The timestamp showing when the articles processed with the given task start to be available for ordering to the customer',
   PROCESSING_ACTIVITY_WH_AREA_CD      VARCHAR(10)     COMMENT 'The activity area code shows in which area within the warehouse the processing activity took place (e.g. at the doors of the warehouse).',
   TASK_LOAD_NET_WEIGHT_MEAS           NUMBER(38, 5)   COMMENT 'The net weight of all loaded articles processed with the particular task',
   WEIGHT_UOM_SID                      NUMBER          COMMENT 'Unit of measurement for weight',
   WEIGHT_UOM_CD                       VARCHAR(5)      COMMENT 'A code for the unit of measure for weight',
   TASK_LOAD_NET_VOLUME_MEAS           NUMBER(38, 5)   COMMENT 'The net volume of all loaded articles processed with the particular task',
   VOLUME_UOM_SID                      NUMBER          COMMENT 'Unit of measurement for volume',
   VOLUME_UOM_CD                       VARCHAR(5)      COMMENT 'A code for the unit of measure for volume',
   CERTIFICATE_NR                      VARCHAR(5)      COMMENT 'The certificate number is relevant only for wine articles and denotes in which year they were produced. One task can process only wines produced in the same year as they are going to be sorted into e specific section within the warehouse.',
   ALT_UOM_CD                          VARCHAR(5)      COMMENT 'A code for an alternative unit of measure of the processed product quantity (e.g. instead of processing the products as single items, they could be processed in boxes).',
   ALT_UOM_PROD_QTY                    NUMBER(38, 5)   COMMENT 'The actual processed product quantity in the alternative Unit of Measure.',
   WH_PROCESS_CAT_CD                   VARCHAR(5)      COMMENT 'This code defines the warehouse process category (e,g, 1 - Putaway, 2 - Stock Removal, 3 - Internal Warehouse Movement, 4 - Physical Inventory, etc.)',
   SGUID_HU_CD                         VARCHAR(100)    COMMENT 'Identifier',
   DGUID_HU_CD                         VARCHAR(100)    COMMENT 'Identifier',
   WH_PROCESSING_EXCEPTION_CD          VARCHAR(5)      COMMENT 'This code describes exceptions which took place during processing of the warehouse task because of unexpected issues. (e.g. ZHBD = Change Destination Bin and storage type - this code can be chosen whenever the destination for a putaway task had to be changed because the initially chosen shelf was broken/dirty, etc.)',
   DWH_CREATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   DWH_UPDATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
   DWH_SRC_FILE_NAME                   VARCHAR(255)    NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
   SRC_FILE_TMSP                       TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',   
   CONSTRAINT PK_T_ETL_WAREHOUSE_CONFIRMED_PROCESSING_L9V PRIMARY KEY (WH_SID, TASK_ID, TASK_POS_NR) NOT ENFORCED 
)  COMMENT = 'ETL  table to support loading confirmed warehouse processings in T_FACT_WAREHOUSE_PROCESSING from the L9V source system (/SCWM/ORDIM_C). This is one of the tables that will replace t_etl_warehouse_processing_task.';
